*{box-sizing:border-box} :root{--ink:#17231e;--muted:#758079;--forest:#18362e;--moss:#54745c;--gold:#bd9757;--paper:#f6f5ef;--line:#e4e6dc} body{margin:0;background:#f7f7f2;color:var(--ink);font-family:'DM Sans',sans-serif;font-size:13px}button{font:inherit;color:inherit;cursor:pointer} .shell{max-width:1440px;margin:auto;padding:0 6.1%} .topbar{height:80px;display:flex;align-items:center;border-bottom:1px solid #e8e9e2;gap:8.5%}.brand{display:flex;align-items:center;gap:10px;color:#21392f;text-decoration:none;font:19px 'Marcellus',serif;letter-spacing:1.1px;line-height:1}.brand-mark{font-size:29px;color:#ba995c}.brand-light{font-size:15px;color:#79877c}.brand small{display:block;color:#9a9f96;font:8px 'DM Sans',sans-serif;letter-spacing:2px;margin-top:6px}.main-nav{display:flex;align-self:stretch;gap:34px}.nav-item{border:0;background:none;color:#818980;font-size:12px;position:relative;padding:0 2px}.nav-item.active{color:#243d31;font-weight:700}.nav-item.active:after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:2px;background:#a98c53}.nav-count{display:inline-grid;place-items:center;width:17px;height:17px;border-radius:20px;background:#e8ede7;font-size:10px;margin-left:4px}.top-resources{margin-left:auto;display:flex;align-items:center;gap:19px}.resource{display:flex;align-items:center;gap:7px;color:#36453d;font-size:12px}.resource-icon{font-size:16px}.berry{color:#a44949}.wood{color:#927146}.stone{color:#737f80}.avatar{border:0;background:#e7e8dc;color:#46614d;border-radius:50%;width:32px;height:32px;font:bold 12px 'Marcellus';margin-left:3px}.welcome-row{padding:27px 0 23px;display:flex;align-items:center;justify-content:space-between}.eyebrow{font-size:9px;letter-spacing:1.55px;color:#80877e;font-weight:700}.welcome-row .eyebrow{display:flex;align-items:center;gap:8px}.live-dot,.online-dot{width:6px;height:6px;display:inline-block;background:#8ba477;border-radius:50%}.eyebrow-line{width:21px;height:1px;background:#d9d9ce;margin:0 1px}.welcome-row h1{font:34px 'Marcellus',serif;margin:8px 0 4px;letter-spacing:-.4px}.welcome-row h1 em,.section-title h2 em{font-weight:400;color:#708167}.welcome-copy{margin:0;color:#7e877e;font-size:12px}.icon-button{border:1px solid #e5e6de;background:#fff;border-radius:5px;padding:8px 11px;color:#66746a;font-size:13px}.icon-button span{font-size:10px;margin-left:6px;color:#92988e}.game-layout{display:grid;grid-template-columns:minmax(0,1.77fr) minmax(310px,.88fr);gap:20px}.world-column{min-width:0}.world-frame{height:440px;position:relative;border-radius:8px;overflow:hidden;background:#9fb480;box-shadow:0 8px 28px #19352812}#world{display:block;width:100%;height:100%;cursor:crosshair;outline:none}.world-topline{position:absolute;left:17px;right:17px;top:15px;display:flex;justify-content:space-between;pointer-events:none}.location-pill,.weather-pill{height:27px;display:flex;align-items:center;gap:8px;background:#f8f6ecd9;border:1px solid #fdfcf3a8;border-radius:4px;padding:0 10px;color:#304536;font-size:9px;font-weight:700;letter-spacing:.7px;box-shadow:0 2px 6px #20362413}.location-pill span{font-size:13px;color:#a4834e}.weather-pill{font-weight:500;letter-spacing:0;color:#586454}.weather-pill span{color:#b48e50;font-size:15px}.weather-pill i{height:3px;width:3px;border-radius:50%;background:#a5a991}.map-controls{position:absolute;right:16px;bottom:57px;display:grid;gap:4px}.map-controls button{border:0;background:#f7f6ecde;width:27px;height:27px;border-radius:4px;color:#53634f;font-size:18px;line-height:1}.world-hint{position:absolute;bottom:15px;left:17px;color:#f8f7e7;text-shadow:0 1px 3px #203424;font-size:8px;font-weight:700;letter-spacing:1px}.keycap{border:1px solid #f3f2d580;border-radius:3px;padding:3px 4px;color:#fff}.hint-divider{margin:0 6px;color:#e5dfb2}.world-footer{height:35px;display:flex;justify-content:space-between;align-items:center;padding:0 3px}.legend{display:flex;gap:18px}.legend span{display:flex;align-items:center;gap:6px;color:#778077;font-size:9px}.legend i{width:7px;height:7px;border-radius:50%;display:inline-block}.legend-player{background:#e8d39a;border:1px solid #84774e}.legend-dragon{background:#b06456}.legend-harvest{background:#d39d55}.text-button{border:0;background:none;color:#718068;font-size:10px;font-weight:600}.text-button span{color:#b28f57;margin-left:4px}.side-column{display:grid;grid-template-rows:1.16fr 1fr;gap:13px;min-height:475px}.side-card{border:1px solid #e8e9e0;background:#fff;border-radius:7px;padding:16px 18px}.card-label{font-size:9px;letter-spacing:1.4px;font-weight:700;color:#78837a;display:flex;align-items:center;gap:7px}.label-icon{font-size:14px;color:#ba995c}.online-dot{margin-left:auto;width:5px;height:5px}.companion-card{position:relative;display:flex;flex-direction:column}.companion-stage{height:94px;position:relative;display:flex;align-items:center;justify-content:center;overflow:hidden;margin-top:3px}.stage-glow{position:absolute;width:135px;height:80px;border-radius:50%;background:radial-gradient(ellipse,#eceddd 0,#f6f5ed 48%,transparent 73%)}.companion-art{position:relative;z-index:1;font-size:57px;filter:drop-shadow(0 7px 4px #2c382a22);transition:transform .3s}.companion-art.bob{animation:bob 3s ease-in-out infinite}@keyframes bob{50%{transform:translateY(-5px) rotate(3deg)}}.stage-caption{position:absolute;right:0;bottom:4px;font:italic 10px 'Marcellus',serif;color:#9a9e8e}.companion-info{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #f0f0ea;padding:10px 0 7px}.companion-info h2{font:18px 'Marcellus',serif;margin:0 0 3px}.companion-info p{margin:0;color:#879087;font-size:10px}.rarity-badge{font-size:8px;letter-spacing:1px;color:#9b8256;background:#f6f2e7;padding:5px 7px;border-radius:3px}.bond-wrap{margin:2px 0 10px}.bond-head{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.8px;color:#878d81}.bond-head b{font-size:9px;letter-spacing:0;color:#63745f}.bond-track,.progress-track{height:4px;background:#e9ece5;border-radius:8px;margin-top:6px;overflow:hidden}.bond-track i,.progress-track i{height:100%;width:0;display:block;background:linear-gradient(90deg,#879c72,#bdab70);border-radius:8px;transition:width .35s}.primary-button{display:flex;align-items:center;width:100%;height:37px;border:0;border-radius:4px;background:#254739;color:#fff;padding:0 12px;text-align:left;font-size:10px;font-weight:600;letter-spacing:.2px;box-shadow:0 3px 7px #1e3e2d17}.primary-button:hover{background:#315c46}.button-icon{color:#d5c188;font-size:14px;margin-right:8px}.button-arrow{margin-left:auto;color:#d9cca4;font-size:15px}.button-note{text-align:center;color:#98a096;font-size:8px;margin-top:6px}.quest-card{padding:16px 18px 13px}.card-heading{display:flex;justify-content:space-between;align-items:center}.card-heading h3{font:18px 'Marcellus',serif;margin:5px 0 0}.quest-seal{width:31px;height:31px;border:1px solid #ece8d8;border-radius:50%;display:grid;place-items:center;color:#b29a60;font-size:16px}.quest-intro{font-size:10px;color:#848c82;margin:8px 0 10px}.quest-step{height:40px;border-top:1px solid #f0f1eb;display:flex;align-items:center;gap:9px}.step-check{width:18px;height:18px;flex:none;border:1px solid #dedfd6;border-radius:50%;display:grid;place-items:center;font-size:9px;color:#969d91}.step-check.done{background:#7c9271;color:white;border-color:#7c9271}.quest-step div{display:grid;gap:2px}.quest-step b{font-size:9px;color:#37463b}.quest-step small{font-size:8px;color:#92998e}.step-reward{margin-left:auto;color:#8b8b73;font-size:8px;white-space:nowrap}.step-reward i{color:#ac6b54;font-style:normal}.quest-progress{border-top:1px solid #eff0e9;margin-top:2px;padding-top:8px}.quest-progress>div:first-child{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.6px;color:#92988d}.quest-progress b{font-size:8px;letter-spacing:0;color:#72816e}.progress-track{height:3px;margin-top:6px}.bottom-row{padding:27px 0 17px}.section-title{display:flex;align-items:end;justify-content:space-between;margin-bottom:12px}.section-title h2{font:22px 'Marcellus',serif;margin:4px 0 0}.discovery-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.discovery-card{border:1px solid #e8e9df;border-radius:5px;background:#fff;display:flex;align-items:center;gap:10px;padding:9px 11px;min-height:58px}.discovery-art{width:39px;height:39px;border-radius:50%;display:grid;place-items:center;font-size:24px;background:#edf0e7;flex:none}.discovery-copy{min-width:0}.discovery-copy b{font:13px 'Marcellus',serif;display:block;color:#38483c}.discovery-copy small{color:#8f968a;font-size:8px}.discovery-state{margin-left:auto;font-size:8px;color:#a3a99d;white-space:nowrap}.discovery-card.owned{border-color:#d4dfd1;background:#fbfcf8}.discovery-card.owned .discovery-art{background:#e1ebdd}.discovery-card.owned .discovery-state{color:#6d8b69}.bottom-row+.foo{}footer{height:44px;border-top:1px solid #e7e9e0;display:flex;justify-content:space-between;align-items:center;color:#a0a59a;font-size:9px}footer span:first-child{letter-spacing:1px;color:#718071;font-family:'Marcellus',serif}.save-dot{display:inline-block;width:5px;height:5px;background:#92ad83;border-radius:50%;margin-left:4px}.joystick{display:none}.build-banner{position:absolute;top:55px;left:50%;transform:translateX(-50%);white-space:nowrap;border:1px solid #dfd6b3;background:#f5f0dff2;padding:8px 12px;border-radius:4px;color:#645834;font-size:9px;letter-spacing:.7px;font-weight:700}.build-banner button{border:0;background:none;text-decoration:underline;color:#746745;margin-left:10px;font-size:9px}.toast{position:fixed;z-index:20;bottom:22px;left:50%;transform:translate(-50%,20px);background:#223d31;color:#fff;padding:11px 17px;border-radius:5px;font-size:11px;box-shadow:0 5px 22px #17231e3d;opacity:0;pointer-events:none;transition:.24s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:30;background:#14251ec7;display:grid;place-items:center;padding:20px;backdrop-filter:blur(4px)}.modal-backdrop[hidden]{display:none}.modal{position:relative;width:min(620px,100%);max-height:min(80vh,670px);overflow:auto;background:#fbfaf5;border-radius:8px;padding:30px 32px;box-shadow:0 20px 70px #0005}.modal-close{position:absolute;right:17px;top:13px;border:0;background:none;font-size:24px;color:#829083}.modal-eyebrow{font-size:9px;letter-spacing:1.7px;color:#9a875e;font-weight:700}.modal h2{font:28px 'Marcellus',serif;margin:6px 0 18px}.modal-content{color:#657065}.modal-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.modal-dragon{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid #e7e9df;background:#fff;border-radius:5px}.modal-dragon .discovery-art{width:48px;height:48px;font-size:28px}.modal-dragon b{font:15px 'Marcellus',serif;display:block;color:#314335}.modal-dragon small{font-size:9px;color:#8a9387}.modal-dragon .owned-tag{margin-left:auto;font-size:8px;color:#779071}.armory-list,.build-list{display:grid;gap:9px}.armor-item,.build-item{display:flex;align-items:center;gap:13px;padding:12px;border:1px solid #e6e8df;border-radius:5px;background:#fff}.armor-icon,.build-icon{font-size:27px;width:42px;text-align:center}.armor-item div:nth-child(2),.build-item div:nth-child(2){flex:1}.armor-item b,.build-item b{display:block;color:#35473b;font:15px 'Marcellus',serif}.armor-item small,.build-item small{font-size:9px;color:#858e83}.armor-item button,.build-item button{border:1px solid #dfe4da;background:#edf2ea;color:#486044;padding:7px 10px;border-radius:4px;font-size:9px;font-weight:700}.armor-item button:disabled,.build-item button:disabled{opacity:.5;cursor:not-allowed}.guide-content{font-size:12px;line-height:1.7}.guide-content strong{color:#35493a}.modal-tabs{display:flex;gap:8px;margin-bottom:13px}.modal-tabs button{border:1px solid #e1e4da;background:#fff;color:#6b796b;padding:7px 11px;border-radius:4px;font-size:9px}.modal-tabs button.active{background:#385541;color:#fff;border-color:#385541}
@media(max-width:1000px){.shell{padding:0 3%}.topbar{gap:5%}.main-nav{gap:20px}.game-layout{grid-template-columns:minmax(0,1.4fr) minmax(285px,.9fr);gap:13px}.world-frame{height:410px}.side-card{padding:14px}.side-column{min-height:445px}.companion-stage{height:80px}.discovery-strip{grid-template-columns:repeat(2,1fr)}}
@media(max-width:700px){body{font-size:12px}.shell{padding:0 16px}.topbar{height:63px;gap:0;justify-content:space-between}.brand{font-size:16px;gap:7px}.brand-mark{font-size:24px}.brand small{font-size:6px;letter-spacing:1.3px}.main-nav{position:fixed;z-index:15;bottom:0;left:0;right:0;height:56px;background:#fbfaf5;border-top:1px solid #e5e7df;justify-content:space-around;gap:0;padding:0 10px env(safe-area-inset-bottom);box-shadow:0 -4px 15px #1b2b2010}.nav-item{font-size:10px;flex:1}.nav-item.active:after{top:0;bottom:auto}.top-resources{gap:10px}.resource{gap:4px;font-size:10px}.resource-icon{font-size:14px}.avatar{width:28px;height:28px}.welcome-row{padding:20px 0 17px}.welcome-row h1{font-size:29px}.welcome-copy{font-size:10px}.welcome-row .eyebrow{font-size:8px}.sound-toggle{padding:7px}.sound-toggle span{display:none}.game-layout{display:flex;flex-direction:column;gap:12px}.world-frame{height:min(64vw,385px);min-height:270px;border-radius:6px}.world-topline{left:10px;right:10px;top:10px}.location-pill,.weather-pill{font-size:8px;padding:0 7px;height:24px}.weather-pill{gap:5px}.world-hint{display:none}.map-controls{right:9px;bottom:10px}.map-controls button{background:#f7f6ecea}.joystick{display:grid;position:absolute;left:10px;bottom:10px;width:100px;height:88px;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:3px;touch-action:none}.joystick button{border:1px solid #f4f2dc88;border-radius:4px;background:#19382ec2;color:#fff;font-size:16px;box-shadow:0 1px 5px #1a2e2670;touch-action:none}.joy-up{grid-column:2;grid-row:1}.joy-left{grid-column:1;grid-row:2}.joy-down{grid-column:2;grid-row:2}.joy-right{grid-column:3;grid-row:2}.world-footer{height:28px}.legend{gap:11px}.legend span{font-size:8px}.text-button{font-size:9px}.side-column{display:flex;flex-direction:column;gap:10px;min-height:0}.companion-card{min-height:278px;padding:13px 15px}.companion-stage{height:76px}.companion-art{font-size:48px}.quest-card{padding:14px 15px}.quest-step{height:38px}.bottom-row{padding:22px 0 14px}.section-title h2{font-size:19px}.section-title .eyebrow{font-size:8px}.discovery-strip{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.discovery-card{padding:7px;gap:7px;min-height:53px}.discovery-art{width:33px;height:33px;font-size:20px}.discovery-copy b{font-size:11px}.discovery-copy small{font-size:7px}.discovery-state{font-size:7px}footer{margin-bottom:56px;height:38px;font-size:8px}.build-banner{top:45px;font-size:8px;padding:7px}.modal{padding:25px 19px}.modal h2{font-size:24px}.modal-grid{grid-template-columns:1fr}.modal-dragon{padding:9px}}
@media(max-width:380px){.shell{padding:0 11px}.top-resources{gap:7px}.resource{font-size:9px}.section-title h2{font-size:17px}.discovery-card{gap:5px;padding:6px}.discovery-art{width:29px;height:29px;font-size:18px}.discovery-copy b{font-size:10px}.discovery-state{font-size:6px}}

(() => {
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const W = 1000, H = 560;
  const species = [
    {id:'ember',name:'Emberling',kind:'Cinder dragon',emoji:'🐲',color:'#cb7758',wing:'#e8a26b',accent:'#f2ce83',rarity:'COMMON',bio:'A bright-hearted little spark with a talent for warming cold mornings.'},
    {id:'moss',name:'Mosswing',kind:'Grove dragon',emoji:'🐉',color:'#77966c',wing:'#aec295',accent:'#d9c878',rarity:'UNCOMMON',bio:'A gentle forest keeper whose wings carry the scent of rain and pine.'},
    {id:'glimmer',name:'Glimmerfin',kind:'River dragon',emoji:'🐲',color:'#7195a0',wing:'#a9c7c0',accent:'#e3d28d',rarity:'RARE',bio:'A shy creek-dancer, said to follow the moonlit bends of the river.'},
    {id:'frost',name:'Frosthorn',kind:'Mountain dragon',emoji:'🐉',color:'#8a8ca8',wing:'#b7bdd3',accent:'#e6d7b3',rarity:'RARE',bio:'A quiet highland wanderer with a heart softer than fresh snow.'},
    {id:'sun',name:'Sunscale',kind:'Dawn dragon',emoji:'🐲',color:'#d2a256',wing:'#e8c984',accent:'#f4e3a9',rarity:'LEGENDARY',bio:'A radiant wanderer glimpsed only where day first touches the hills.'}
  ];
  const forage = [
    {x:215,y:265,type:'bloom',name:'Meadow blooms',color:'#d5a25e',taken:false},
    {x:795,y:345,type:'bloom',name:'Meadow blooms',color:'#c87975',taken:false},
    {x:480,y:125,type:'bloom',name:'Meadow blooms',color:'#d4b768',taken:false},
    {x:880,y:188,type:'wood',name:'Fallen branches',color:'#8c6844',taken:false},
    {x:115,y:425,type:'stone',name:'Mossy stones',color:'#929b87',taken:false},
    {x:680,y:470,type:'bloom',name:'Meadow blooms',color:'#ba83a1',taken:false}
  ];
  const wild = [
    {species:'ember',x:600,y:310,trust:0}, {species:'moss',x:340,y:230,trust:0},
    {species:'glimmer',x:760,y:205,trust:0}, {species:'frost',x:440,y:430,trust:0}
  ];
  const initial = {player:{x:500,y:330},owned:[],companion:null,berries:3,wood:8,stone:5,forageCount:0,buildings:[],armor:[],equipped:null,rewarded:[],day:1};
  let state;
  try { state = {...initial,...JSON.parse(localStorage.getItem('mythwyld-save')||'{}')}; state.player={...initial.player,...(state.player||{})}; }
  catch { state={...initial,player:{...initial.player}}; }
  const keys = new Set(); let zoom=1, buildChoice=null, toastTimer, lastTime=0, sound=false;
  let pointerTarget=null;
  function save(){localStorage.setItem('mythwyld-save',JSON.stringify(state)); updateUI();}
  function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
  function getSpecies(id){return species.find(s=>s.id===id)}
  function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
  function nearestDragon(){return wild.filter(d=>!state.owned.includes(d.species)).sort((a,b)=>distance(a,state.player)-distance(b,state.player))[0]}
  function closeForage(){return forage.filter(f=>!f.taken).sort((a,b)=>distance(a,state.player)-distance(b,state.player))[0]}
  function updateUI(){
    document.getElementById('berry-count').textContent=state.berries;
    document.getElementById('wood-count').textContent=state.wood;
    document.getElementById('stone-count').textContent=state.stone;
    document.getElementById('dragon-count').textContent=state.owned.length;
    document.getElementById('day-count').textContent=String(state.day).padStart(2,'0');
    const companion=getSpecies(state.companion);
    const art=document.getElementById('companion-art');
    art.textContent=companion?companion.emoji:'🐉'; art.classList.toggle('bob',!!companion);
    document.getElementById('companion-name').textContent=companion?companion.name:'No companion yet';
    document.getElementById('companion-subtitle').textContent=companion?companion.kind+' · Your kindred':'Your first dragon is out there.';
    document.getElementById('companion-rarity').textContent=companion?companion.rarity:'WILD';
    document.getElementById('companion-caption').textContent=companion?'Your bond grows every day':'A bond is waiting to begin';
    const dragon=nearestDragon(), nearD=dragon&&distance(dragon,state.player)<80, node=closeForage(), nearF=node&&distance(node,state.player)<57;
    const btn=document.getElementById('interact-label'), note=document.getElementById('button-note'), bond=document.getElementById('bond-wrap');
    if(buildChoice){btn.textContent='Place '+buildChoice.name;note.textContent='Tap an open spot on the meadow';}
    else if(nearD){btn.textContent=dragon.trust>=2?'Offer a bonding treat':'Offer a wild berry';note.textContent=dragon.trust>=2?'One more kind gesture, and you’ll be kindred':'A little kindness goes a long way';}
    else if(nearF){btn.textContent=node.type==='bloom'?'Gather meadow blooms':'Gather '+node.name.toLowerCase();note.textContent='A little forage for your pack';}
    else {btn.textContent=companion?'Explore the meadow':'Explore the meadow';note.textContent=dragon?'Walk close to a dragon to begin a bond':'Wander the meadow to find wild dragons';}
    bond.style.display=nearD?'block':'none';
    if(nearD){document.getElementById('bond-text').textContent=dragon.trust>=3?'Ready to bond':`${dragon.trust} of 3 treats`;document.getElementById('bond-fill').style.width=Math.min(100,dragon.trust/3*100)+'%';}
    updateQuest(); renderDiscoveries();
  }
  function updateQuest(){
    const dragon=state.owned.length>0, gathered=state.forageCount>=3, cottage=state.buildings.some(b=>b.id==='cottage');
    const steps=[dragon,gathered,cottage];
    ['step-dragon','step-forage','step-build'].forEach((id,i)=>{const el=document.getElementById(id);el.classList.toggle('done',steps[i]);el.textContent=steps[i]?'✓':String(i+1)});
    const done=steps.filter(Boolean).length;document.getElementById('quest-progress').textContent=`${done} / 3 complete`;document.getElementById('quest-bar').style.width=(done/3*100)+'%';
    if(dragon&&!state.rewarded.includes('dragon')){state.rewarded.push('dragon');state.berries+=3;toast('Kindred found! +3 wild berries');}
    if(gathered&&!state.rewarded.includes('forage')){state.rewarded.push('forage');state.wood+=6;toast('Foraging done! +6 timber');}
    if(cottage&&!state.rewarded.includes('cottage')){state.rewarded.push('cottage');if(!state.armor.includes('mantle'))state.armor.push('mantle');toast('Your first haven! Forest mantle unlocked');}
    localStorage.setItem('mythwyld-save',JSON.stringify(state));
  }
  function renderDiscoveries(){
    const el=document.getElementById('discovery-strip');
    el.innerHTML=species.slice(0,4).map(s=>`<div class="discovery-card ${state.owned.includes(s.id)?'owned':''}"><div class="discovery-art">${s.emoji}</div><div class="discovery-copy"><b>${s.name}</b><small>${s.kind}</small></div><span class="discovery-state">${state.owned.includes(s.id)?'✦ KINDRED':'UNDISCOVERED'}</span></div>`).join('');
  }
  function interact(){
    if(buildChoice){toast('Choose an open spot in the meadow');return;}
    const dragon=nearestDragon();
    if(dragon&&distance(dragon,state.player)<80){
      if(state.berries<1){toast('You need a wild berry to offer. Forage among the flowers.');return;}
      state.berries--; dragon.trust++;
      if(dragon.trust>=3){const s=getSpecies(dragon.species);state.owned.push(s.id);state.companion=state.companion||s.id;wild.splice(wild.indexOf(dragon),1);toast(`${s.name} trusts you. A new kindred!`);}
      else toast(`${getSpecies(dragon.species).name} accepts your treat. Trust is growing…`);
      save();return;
    }
    const node=closeForage();
    if(node&&distance(node,state.player)<57){
      node.taken=true;
      if(node.type==='bloom'){state.berries+=2;state.forageCount++;toast('Gathered meadow blooms · +2 berries');}
      else if(node.type==='wood'){state.wood+=3;toast('Gathered fallen branches · +3 timber');}
      else {state.stone+=2;toast('Found mossy stones · +2 stone');}
      save();return;
    }
    toast('Wander closer to a dragon or a forage patch');
  }
  function movePlayer(dx,dy,dt){
    const speed=170*dt;let x=0,y=0;
    if(keys.has('ArrowUp')||keys.has('w')||keys.has('W')||keys.has('up'))y--;
    if(keys.has('ArrowDown')||keys.has('s')||keys.has('S')||keys.has('down'))y++;
    if(keys.has('ArrowLeft')||keys.has('a')||keys.has('A')||keys.has('left'))x--;
    if(keys.has('ArrowRight')||keys.has('d')||keys.has('D')||keys.has('right'))x++;
    if(pointerTarget){const tx=pointerTarget.x-state.player.x,ty=pointerTarget.y-state.player.y,dist=Math.hypot(tx,ty);if(dist<8)pointerTarget=null;else{x+=tx/dist;y+=ty/dist;}}
    const mag=Math.hypot(x,y);if(mag){state.player.x=Math.max(50,Math.min(W-50,state.player.x+x/mag*speed));state.player.y=Math.max(80,Math.min(H-40,state.player.y+y/mag*speed));}
  }
  function roundedRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
  function drawBackground(){
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#a9bd8c');g.addColorStop(.58,'#9bb17c');g.addColorStop(1,'#879f6d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // rolling clearings and a pale, winding footpath
    ctx.fillStyle='#b9c597';ctx.beginPath();ctx.ellipse(510,280,360,235,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#c8c59d';ctx.beginPath();ctx.moveTo(-50,476);ctx.bezierCurveTo(170,425,191,337,349,341);ctx.bezierCurveTo(476,348,489,488,675,454);ctx.bezierCurveTo(826,425,811,301,1040,299);ctx.lineTo(1040,348);ctx.bezierCurveTo(858,353,891,487,690,507);ctx.bezierCurveTo(468,530,457,388,348,386);ctx.bezierCurveTo(229,382,180,469,-50,521);ctx.fill();
    ctx.strokeStyle='#d3cea8';ctx.lineWidth=2;ctx.stroke();
    // distant hills
    ctx.fillStyle='#7f9b76';ctx.beginPath();ctx.moveTo(0,120);ctx.quadraticCurveTo(120,70,230,124);ctx.quadraticCurveTo(355,55,480,118);ctx.quadraticCurveTo(620,55,743,121);ctx.quadraticCurveTo(870,70,1000,125);ctx.lineTo(1000,165);ctx.lineTo(0,165);ctx.fill();
    // river pool
    ctx.fillStyle='#7da3a0';ctx.beginPath();ctx.moveTo(890,0);ctx.bezierCurveTo(840,72,920,91,868,151);ctx.bezierCurveTo(832,195,920,225,886,267);ctx.lineTo(1000,267);ctx.lineTo(1000,0);ctx.fill();
    ctx.strokeStyle='#bdd0b1';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(900,0);ctx.bezierCurveTo(855,64,938,95,881,151);ctx.stroke();
    // soft painterly ground flecks
    for(let i=0;i<80;i++){let x=(i*173+39)%W,y=(i*97+21)%H;ctx.fillStyle=i%2?'#e1d7a833':'#496c4930';ctx.beginPath();ctx.ellipse(x,y,3+(i%4),1.5,((i%5)-2)*.3,0,Math.PI*2);ctx.fill();}
    // tree clusters around the clearing
    const trees=[[45,105,1.2],[132,80,.92],[245,100,.88],[370,75,1.05],[536,83,.93],[675,93,1.2],[790,82,.94],[962,90,1.24],[60,198,.8],[148,159,.62],[830,147,.7],[961,202,.9],[35,326,.78],[955,394,.95],[90,519,1.1],[265,517,.78],[557,534,.9],[833,516,1.12],[946,502,.8],[165,280,.53],[933,310,.65]];
    trees.forEach(([x,y,s],i)=>drawTree(x,y,s,i));
    // flower flecks and tufts
    for(let i=0;i<38;i++){const x=(i*271+92)%W,y=(i*149+197)%H;if((x>170&&x<850&&y>120&&y<490)){ctx.strokeStyle=i%3?'#718f5c99':'#e5e0b899';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-2,y-5);ctx.moveTo(x,y);ctx.lineTo(x+2,y-4);ctx.stroke();}}
  }
  function drawTree(x,y,s,i){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#655e43';ctx.fillRect(-3,6,7,18);ctx.fillStyle=i%2?'#537552':'#607e58';ctx.beginPath();ctx.arc(0,0,15,0,Math.PI*2);ctx.arc(-10,6,11,0,Math.PI*2);ctx.arc(10,6,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#789368';ctx.beginPath();ctx.arc(-5,-5,8,0,Math.PI*2);ctx.fill();ctx.restore();}
  function drawDragon(x,y,speciesId,scale=1){
    const s=getSpecies(speciesId);ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#25372630';ctx.beginPath();ctx.ellipse(0,14,24,7,0,0,Math.PI*2);ctx.fill();
    // curled tail
    ctx.strokeStyle=s.color;ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-14,3);ctx.bezierCurveTo(-31,12,-34,-6,-43,-4);ctx.stroke();
    // rear wing
    ctx.fillStyle=s.wing;ctx.beginPath();ctx.moveTo(-5,-7);ctx.quadraticCurveTo(-22,-29,-33,-27);ctx.quadraticCurveTo(-26,-13,-33,-5);ctx.quadraticCurveTo(-19,-8,-13,4);ctx.closePath();ctx.fill();
    // body
    ctx.fillStyle=s.color;ctx.beginPath();ctx.ellipse(-1,1,20,13,-.1,0,Math.PI*2);ctx.fill();
    // belly
    ctx.fillStyle=s.accent;ctx.beginPath();ctx.ellipse(3,7,11,6,.1,0,Math.PI);ctx.fill();
    // neck and head
    ctx.strokeStyle=s.color;ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(9,-1);ctx.quadraticCurveTo(15,-13,16,-19);ctx.stroke();ctx.fillStyle=s.color;ctx.beginPath();ctx.ellipse(20,-19,12,9,-.15,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(27,-18);ctx.lineTo(38,-13);ctx.lineTo(26,-10);ctx.closePath();ctx.fill();
    // horns and back spines
    ctx.fillStyle=s.accent;ctx.beginPath();ctx.moveTo(15,-26);ctx.lineTo(12,-36);ctx.lineTo(21,-26);ctx.moveTo(23,-25);ctx.lineTo(28,-34);ctx.lineTo(28,-23);ctx.fill();
    ctx.fillStyle=s.wing;for(let i=0;i<4;i++){let px=-12+i*7;ctx.beginPath();ctx.moveTo(px,-8);ctx.lineTo(px+3,-16-(i%2)*3);ctx.lineTo(px+7,-7);ctx.fill();}
    // feet
    ctx.strokeStyle=s.color;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-10,9);ctx.lineTo(-12,16);ctx.moveTo(8,9);ctx.lineTo(10,16);ctx.stroke();
    ctx.fillStyle='#263323';ctx.beginPath();ctx.arc(22,-21,1.5,0,Math.PI*2);ctx.fill();ctx.restore();
  }
  function drawPlayer(){
    const p=state.player;ctx.fillStyle='#24362832';ctx.beginPath();ctx.ellipse(p.x,p.y+13,14,5,0,0,Math.PI*2);ctx.fill();
    if(state.companion){drawDragon(p.x-28,p.y+2,state.companion,.55);}
    // boots / cloak / hood
    ctx.fillStyle='#554b3b';ctx.fillRect(p.x-6,p.y+6,5,8);ctx.fillRect(p.x+2,p.y+6,5,8);
    ctx.fillStyle=state.armor.includes('mantle')?'#657e61':'#9a7352';ctx.beginPath();ctx.moveTo(p.x,p.y-12);ctx.lineTo(p.x-11,p.y+8);ctx.quadraticCurveTo(p.x,p.y+14,p.x+11,p.y+8);ctx.lineTo(p.x+5,p.y-10);ctx.closePath();ctx.fill();
    ctx.fillStyle='#d8bf8c';ctx.beginPath();ctx.arc(p.x,p.y-12,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#435543';ctx.beginPath();ctx.arc(p.x,p.y-15,7,Math.PI,Math.PI*2);ctx.lineTo(p.x+6,p.y-11);ctx.lineTo(p.x-6,p.y-11);ctx.fill();
    ctx.fillStyle='#eee4c6';ctx.beginPath();ctx.arc(p.x+2,p.y-12,1,0,Math.PI*2);ctx.fill();
  }
  function drawForage(f){if(f.taken)return;ctx.save();ctx.translate(f.x,f.y);ctx.fillStyle='#33422a22';ctx.beginPath();ctx.ellipse(0,5,13,4,0,0,Math.PI*2);ctx.fill();if(f.type==='bloom'){for(let i=0;i<5;i++){ctx.fillStyle=f.color;ctx.beginPath();ctx.arc(Math.cos(i*1.25)*4,Math.sin(i*1.25)*4,3,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#e8cc72';ctx.beginPath();ctx.arc(0,0,2.4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#61734c';ctx.beginPath();ctx.moveTo(0,3);ctx.lineTo(0,10);ctx.stroke();}else if(f.type==='wood'){ctx.strokeStyle=f.color;ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-9,2);ctx.lineTo(7,-2);ctx.moveTo(-3,4);ctx.lineTo(10,1);ctx.stroke();}else{ctx.fillStyle=f.color;ctx.beginPath();ctx.ellipse(-4,1,5,3,-.4,0,Math.PI*2);ctx.ellipse(3,0,5,4,.3,0,Math.PI*2);ctx.fill();}ctx.restore();}
  function drawBuilding(b){ctx.save();ctx.translate(b.x,b.y);ctx.fillStyle='#3b3e2d38';ctx.beginPath();ctx.ellipse(0,19,43,12,0,0,Math.PI*2);ctx.fill();if(b.id==='cottage'){ctx.fillStyle='#b89c6d';ctx.fillRect(-31,-7,62,29);ctx.fillStyle='#725b44';ctx.beginPath();ctx.moveTo(-39,-6);ctx.lineTo(0,-39);ctx.lineTo(39,-6);ctx.closePath();ctx.fill();ctx.fillStyle='#e4cf9c';ctx.fillRect(-6,4,13,18);ctx.fillStyle='#8c7655';ctx.fillRect(-24,0,12,10);ctx.fillRect(12,0,12,10);ctx.strokeStyle='#d8c090';ctx.lineWidth=2;ctx.strokeRect(-24,0,12,10);ctx.strokeRect(12,0,12,10);}else if(b.id==='stable'){ctx.fillStyle='#9e8259';ctx.fillRect(-38,-5,76,28);ctx.fillStyle='#73583e';ctx.beginPath();ctx.moveTo(-43,-5);ctx.lineTo(-28,-28);ctx.lineTo(29,-28);ctx.lineTo(43,-5);ctx.closePath();ctx.fill();ctx.fillStyle='#e2d3ac';ctx.fillRect(-10,7,20,16);ctx.strokeStyle='#705638';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,7);ctx.lineTo(0,23);ctx.stroke();}else{ctx.fillStyle='#83795f';ctx.fillRect(-26,-4,52,27);ctx.fillStyle='#5e5e4d';ctx.beginPath();ctx.moveTo(-32,-4);ctx.lineTo(0,-24);ctx.lineTo(32,-4);ctx.closePath();ctx.fill();ctx.fillStyle='#d18c56';ctx.beginPath();ctx.arc(0,12,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffe0a0';ctx.beginPath();ctx.arc(0,12,4,0,Math.PI*2);ctx.fill();}ctx.restore();}
  function drawWorld(){
    ctx.save();ctx.clearRect(0,0,W,H);ctx.scale(zoom,zoom);const offX=(W-W/zoom)/2,offY=(H-H/zoom)/2;ctx.translate(-offX,-offY);drawBackground();
    forage.forEach(drawForage);state.buildings.forEach(drawBuilding);
    const d=nearestDragon();wild.forEach((w,i)=>{const bob=Math.sin(Date.now()/460+i*2)*2;drawDragon(w.x,w.y+bob,w.species,.83);if(w===d&&distance(w,state.player)<120){ctx.fillStyle='#fff9e6';roundedRect(ctx,w.x-4,w.y-42,8,4,2);ctx.fill();ctx.fillStyle='#89a273';roundedRect(ctx,w.x-4,w.y-42,8*w.trust/3,4,2);ctx.fill();}});
    drawPlayer();
    if(pointerTarget){ctx.strokeStyle='#f9f1d8aa';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(pointerTarget.x,pointerTarget.y,8+Math.sin(Date.now()/120)*2,0,Math.PI*2);ctx.stroke();}
    ctx.restore();
  }
  function frame(ts){const dt=Math.min(.04,(ts-lastTime)/1000||0);lastTime=ts;if(dt){movePlayer(0,0,dt);drawWorld();}requestAnimationFrame(frame)}
  function canvasPoint(e){const r=canvas.getBoundingClientRect();let x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;const ox=(W-W/zoom)/2,oy=(H-H/zoom)/2;return{x:x/zoom+ox,y:y/zoom+oy};}
  function placeBuilding(point){const b=buildChoice;if(!b)return;if(state.wood<b.wood||state.stone<b.stone){toast('Not enough materials');return;}state.wood-=b.wood;state.stone-=b.stone;state.buildings.push({id:b.id,x:point.x,y:point.y});buildChoice=null;document.getElementById('build-banner').hidden=true;save();toast(`${b.name} raised! A little more like home.`);}
  canvas.addEventListener('pointerdown',e=>{const p=canvasPoint(e);if(buildChoice){placeBuilding(p);return;}const near=[...wild,...forage.filter(f=>!f.taken)].find(o=>distance(o,p)<24);if(near){pointerTarget=null;if(distance(state.player,near)<57){interact();}else{pointerTarget={x:near.x,y:near.y};toast('Moving closer…');}}else{pointerTarget=p;}});
  window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='e'||e.key==='E'){interact();return;}if(e.key==='Escape'&&buildChoice){buildChoice=null;document.getElementById('build-banner').hidden=true;updateUI();return;}keys.add(e.key);});
  window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
  document.querySelectorAll('.joystick button').forEach(button=>{const down=e=>{e.preventDefault();keys.add(button.dataset.dir);button.setPointerCapture?.(e.pointerId)};const up=e=>{e.preventDefault();keys.delete(button.dataset.dir)};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up);});
  document.getElementById('interact-button').addEventListener('click',interact);
  document.getElementById('zoom-in').onclick=()=>zoom=Math.min(1.35,zoom+.1);document.getElementById('zoom-out').onclick=()=>zoom=Math.max(.85,zoom-.1);
  document.getElementById('cancel-build').onclick=()=>{buildChoice=null;document.getElementById('build-banner').hidden=true;updateUI()};
  function modal(title,eyebrow,html){document.getElementById('modal-title').textContent=title;document.getElementById('modal-eyebrow').textContent=eyebrow;document.getElementById('modal-content').innerHTML=html;document.getElementById('modal-backdrop').hidden=false;}
  function closeModal(){document.getElementById('modal-backdrop').hidden=true}
  document.getElementById('modal-close').onclick=closeModal;document.getElementById('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
  function openBestiary(){modal('The bestiary','FIELD NOTES',`<div class="modal-grid">${species.map(s=>`<article class="modal-dragon"><div class="discovery-art">${s.emoji}</div><div><b>${s.name}</b><small>${s.kind} · ${s.rarity.toLowerCase()}</small><p style="font-size:9px;line-height:1.45;margin:6px 0 0">${s.bio}</p></div><span class="owned-tag">${state.owned.includes(s.id)?'KINDRED':'WILD'}</span></article>`).join('')}</div>`)}
  const builds=[{id:'cottage',name:'Meadow cottage',icon:'⌂',desc:'A warm little home for long adventures.',wood:6,stone:3},{id:'stable',name:'Dragon stable',icon:'♞',desc:'A roomy roost for your growing kindred.',wood:5,stone:4},{id:'forge',name:'Wayfarer forge',icon:'⚒',desc:'Craft sturdy gear from found materials.',wood:4,stone:5}];
  function openBuilds(){modal('Shape your homestead','BUILDING PLANS',`<p class="guide-content" style="margin-top:-8px">Choose a structure, then tap a clearing on your meadow to place it.</p><div class="build-list">${builds.map(b=>`<div class="build-item"><div class="build-icon">${b.icon}</div><div><b>${b.name}</b><small>${b.desc}<br>▰ ${b.wood} timber &nbsp; ◆ ${b.stone} stone</small></div><button data-build="${b.id}" ${state.wood<b.wood||state.stone<b.stone?'disabled':''}>Place</button></div>`).join('')}</div>`);document.querySelectorAll('[data-build]').forEach(btn=>btn.onclick=()=>{buildChoice=builds.find(b=>b.id===btn.dataset.build);closeModal();document.getElementById('build-banner').hidden=false;updateUI();toast(`Choose a clearing for your ${buildChoice.name.toLowerCase()}`)});}
  const armors=[{id:'mantle',name:'Forest mantle',icon:'🧥',desc:'A soft cloak, woven for the first keepers.',wood:3,stone:0,needs:'Quest reward',unlock:true},{id:'scale',name:'Bronze scale mail',icon:'🛡️',desc:'Light dragon-scale links reinforce your resolve.',wood:2,stone:6,needs:'Needs a wayfarer forge',unlock:false},{id:'moon',name:'Moonveil circlet',icon:'👑',desc:'A moon-silver circlet that catches the starlight.',wood:0,stone:4,needs:'Needs a wayfarer forge',unlock:false}];
  function openArmory(){modal('The wayfarer’s armory','ARMOR & RELICS',`<p class="guide-content" style="margin-top:-8px">Collect armor from your adventures, then craft and equip it here.</p><div class="armory-list">${armors.map(a=>{let crafted=state.armor.includes(a.id),forge=state.buildings.some(b=>b.id==='forge'),unlocked=a.unlock||forge||crafted,afford=state.wood>=a.wood&&state.stone>=a.stone;return `<div class="armor-item"><div class="armor-icon">${a.icon}</div><div><b>${a.name}</b><small>${crafted?'Collected · '+a.desc:(unlocked?a.desc:a.needs)}${a.id==='mantle'&&!crafted?' · Quest reward':''}${unlocked&&!crafted?`<br>▰ ${a.wood} timber &nbsp; ◆ ${a.stone} stone`:''}</small></div><button data-armor="${a.id}" ${(!unlocked||(!crafted&&!afford))?'disabled':''}>${crafted?(state.equipped===a.id?'Equipped':'Equip'):'Craft'}</button></div>`}).join('')}</div>`);document.querySelectorAll('[data-armor]').forEach(btn=>btn.onclick=()=>{const a=armors.find(x=>x.id===btn.dataset.armor);if(state.armor.includes(a.id)){state.equipped=a.id;toast(`${a.name} equipped`);}else if(a.unlock&&!state.rewarded.includes('cottage')){toast('Complete your first-haven quest to unlock this');return;}else{state.wood-=a.wood;state.stone-=a.stone;state.armor.push(a.id);state.equipped=a.id;toast(`${a.name} crafted and equipped`);}save();openArmory();});}
  function openGuide(){modal('A field guide','FIRST STEPS',`<div class="guide-content"><p><strong>Wander</strong> the meadow with WASD, arrow keys, or the touch pad. Tap any spot to walk there. Zoom in for a closer look.</p><p><strong>Make a friend.</strong> Walk near a wild dragon and press <strong>E</strong> or the green button to offer a berry. Three treats build enough trust to bond. Your first kindred will follow you.</p><p><strong>Forage.</strong> Flower patches give two berries. Fallen branches and mossy stones provide building materials. Tap a patch, then get close and interact.</p><p><strong>Build.</strong> Open Building plans below, choose a structure, then tap an open spot in your meadow. A cottage completes your first-haven quest and unlocks the Forest mantle.</p><p><strong>Keep collecting.</strong> Find every dragon, build a stable for your companions, and raise a forge to craft more armor.</p></div>`)}
  document.querySelectorAll('.nav-item').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n===btn));if(btn.dataset.view==='bestiary')openBestiary();if(btn.dataset.view==='armory')openArmory();});
  document.querySelector('[data-open="bestiary"]').onclick=openBestiary;document.getElementById('guide-button').onclick=openGuide;
  document.getElementById('sound-toggle').onclick=e=>{sound=!sound;e.currentTarget.querySelector('span').textContent=sound?'Sound on':'Sound off';toast(sound?'The meadow hums in a gentle breeze':'Ambient sound off');};
  updateUI();
  // Small building affordance tucked into the map on long-press / double click.
  canvas.addEventListener('dblclick',e=>{if(!buildChoice)openBuilds()});
  requestAnimationFrame(frame);
})();

