const initial = {player:{x:500,y:330},owned:[],companion:null,berries:3,wood:8,stone:5,nets:2,sigils:2,dragonProgress:{},forageCount:0,buildings:[],castle:'greenstead',homes:['greenstead'],castleLevel:0,armor:[],equipped:null,furniture:[],placedFurniture:[],rewarded:[],day:1};
