/* Character Studio */
.modal:has(.character-studio){width:min(850px,100%);max-height:min(88vh,780px)}
.character-studio{display:grid;grid-template-columns:minmax(210px,.78fr) minmax(0,1.35fr);gap:25px;align-items:stretch}
.character-preview-wrap{position:relative;min-height:330px;overflow:hidden;border:1px solid #e1e4d7;border-radius:7px;background:radial-gradient(ellipse at 50% 77%,#dfe4d2 0,#edf0e5 34%,#f6f5ee 75%)}
.character-preview-wrap:after{content:'';position:absolute;left:15%;right:15%;bottom:22px;height:22px;border-radius:50%;background:#73836b24;filter:blur(8px);pointer-events:none}
#character-preview{display:block;width:100%;height:100%;min-height:330px;touch-action:none;cursor:grab}
#character-preview:active{cursor:grabbing}
.preview-tip{position:absolute;z-index:1;left:0;right:0;bottom:11px;text-align:center;color:#768071;font-size:8px;letter-spacing:1.35px;pointer-events:none}
.character-editor{min-width:0}
.character-name,.select-grid label{display:grid;gap:7px;color:#667267;font-size:10px;font-weight:600}
.character-name input,.select-grid select{width:100%;height:36px;border:1px solid #dfe3d9;border-radius:4px;padding:0 10px;background:#fff;color:#2d3e32;font:12px 'DM Sans',sans-serif;outline:none}
.character-name input:focus,.select-grid select:focus{border-color:#9caf91;box-shadow:0 0 0 2px #8ba47722}
.editor-label{margin:17px 0 8px;color:#8b8e7e;font-size:8px;font-weight:700;letter-spacing:1.25px}
.design-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.design-chip{min-width:0;display:grid;justify-items:center;gap:4px;padding:7px 3px;border:1px solid #e5e7df;border-radius:5px;background:#fff;color:#667167;font-size:8px;white-space:nowrap;transition:border-color .15s,background .15s}
.design-chip:hover,.design-chip.selected{border-color:#98a98c;background:#f1f4ec;color:#334b39}
.design-chip i{display:block;width:17px;height:17px;border-radius:50%;background:var(--swatch);box-shadow:inset 0 -3px 0 #00000014}
.color-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}
.color-choice{display:grid;justify-items:center;gap:5px;color:#697469;font-size:8px}
.color-choice input{width:29px;height:27px;padding:2px;border:1px solid #e1e4dc;border-radius:4px;background:#fff;cursor:pointer}
.select-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px}
.select-grid select{height:33px;padding:0 7px;font-size:10px}
.toggle-choice{display:flex;align-items:center;gap:7px;margin-top:12px;color:#536456;font-size:10px}
.toggle-choice input{accent-color:#55745b}
.studio-note{margin:11px 0 0;color:#8a9085;font-size:9px;line-height:1.5}
@media(max-width:700px){.modal:has(.character-studio){max-height:calc(100dvh - 26px);padding:24px 18px}.character-studio{grid-template-columns:1fr;gap:12px}.character-preview-wrap{min-height:205px;height:205px}.character-preview-wrap:after{bottom:17px}#character-preview{min-height:205px}.preview-tip{bottom:7px}.character-editor .editor-label{margin-top:13px}.design-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.color-grid{gap:3px}.color-choice input{width:27px;height:25px}}
@media(max-width:380px){.modal:has(.character-studio){padding:22px 13px}.design-chip{font-size:7px;padding:6px 1px}.color-choice{font-size:7px}.color-choice input{width:24px;height:24px}}

